import { nativeModel } from './model.js';

const sha256Pattern = /^[a-f0-9]{64}$/u;
const maximumSqliteInteger = 9223372036854775807n;

// Generated by canonicalNativeSqliteSchema() from the pinned native model and
// fixed EF history/lock tables. This module deliberately does not load SQLite,
// so production startup can validate persisted migration provenance without
// enabling a SQLite runtime. A focused test prevents this literal from drifting
// away from the generator.
export const pinnedNativeSqliteSchemaFingerprint = '24690f1f413cc531c8ed385851cd0e3f392af7ec470860ee3d0348d285133725';
export const pinnedNativeDataMigrationProductVersion = '13.0.0.0';
export const pinnedNativeSqliteMigrationHistory = Object.freeze([
  ...nativeModel.migrations.map(MigrationId => Object.freeze({
    MigrationId,
    ProductVersion: nativeModel.efProductVersion,
  })),
  ...nativeModel.dataMigrations.map(MigrationId => Object.freeze({
    MigrationId,
    ProductVersion: pinnedNativeDataMigrationProductVersion,
  })),
].sort((left, right) => left.MigrationId.localeCompare(right.MigrationId, 'en')));
const pinnedNativeSqliteMigrationIds = Object.freeze(
  pinnedNativeSqliteMigrationHistory.map(row => row.MigrationId));

function plainRecord(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`Invalid ${label}`);
  }
  return value;
}

function exactKeys(value, keys, label) {
  plainRecord(value, label);
  const actual = Object.keys(value).sort(), expected = [...keys].sort();
  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new TypeError(`Invalid ${label}`);
  }
}

function parseStoredInteger(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)
    || Object.keys(value).length !== 1 || typeof value.$integer !== 'string'
    || !/^(?:0|[1-9]\d*)$/u.test(value.$integer)) return value;
  return BigInt(value.$integer);
}

const generatedTables = new Set(nativeModel.tables
  .filter(table => table.columns.some(column => column.generated))
  .map(table => table.name));

/** Validate and normalize the portable shape without loading the SQLite runtime. */
export function normalizeNativeEnvelope(value) {
  exactKeys(value, ['ddl', 'fingerprint', 'history', 'sqliteSequence'], 'native database envelope');
  if (!Array.isArray(value.ddl) || value.ddl.length === 0
    || value.ddl.some(sql => typeof sql !== 'string' || !/^CREATE(?: UNIQUE)? (?:TABLE|INDEX) /iu.test(sql))
    || typeof value.fingerprint !== 'string' || !sha256Pattern.test(value.fingerprint)
    || !Array.isArray(value.history) || !Array.isArray(value.sqliteSequence)) {
    throw new TypeError('Invalid native database envelope');
  }
  const history = value.history.map(row => {
    exactKeys(row, ['MigrationId', 'ProductVersion'], 'native database migration history row');
    if (typeof row.MigrationId !== 'string' || !row.MigrationId
      || typeof row.ProductVersion !== 'string' || !row.ProductVersion) {
      throw new TypeError('Invalid native database migration history row');
    }
    return { MigrationId: row.MigrationId, ProductVersion: row.ProductVersion };
  });
  const sequenceNames = new Set();
  const sqliteSequence = value.sqliteSequence.map(entry => {
    exactKeys(entry, ['name', 'seq'], 'native database sequence row');
    if (typeof entry.name !== 'string' || !generatedTables.has(entry.name) || sequenceNames.has(entry.name)) {
      throw new TypeError('Invalid native database sequence row');
    }
    const seq = typeof entry.seq === 'bigint' ? entry.seq
      : Number.isSafeInteger(entry.seq) && entry.seq >= 0 ? BigInt(entry.seq) : null;
    if (seq === null || seq < 0n || seq > maximumSqliteInteger) throw new TypeError('Invalid native database sequence row');
    sequenceNames.add(entry.name);
    return { name: entry.name, seq };
  });
  return { ddl: [...value.ddl], fingerprint: value.fingerprint, history, sqliteSequence };
}

export function serializeNativeEnvelope(value) {
  return JSON.stringify(normalizeNativeEnvelope(value), (_, item) => typeof item === 'bigint' ? { $integer: item.toString() } : item);
}

/** Validate the production-safe pinned fingerprint and complete migration set.
 * Deep SQLite reconstruction remains an import/export boundary responsibility. */
export function assertPinnedNativeEnvelope(value) {
  const envelope = normalizeNativeEnvelope(value);
  if (envelope.fingerprint !== pinnedNativeSqliteSchemaFingerprint) {
    throw new Error(`Jellyfin database exchange requires pinned Jellyfin schema fingerprint ${pinnedNativeSqliteSchemaFingerprint}`);
  }
  // ProductVersion records the EF/Jellyfin version that originally applied a
  // migration. Upgraded Jellyfin databases legitimately contain mixed values,
  // so compatibility is defined by the complete ordered migration ID set and
  // the source values are preserved verbatim for export.
  if (JSON.stringify(envelope.history.map(row => row.MigrationId))
    !== JSON.stringify(pinnedNativeSqliteMigrationIds)) {
    throw new Error(`Jellyfin database exchange requires the complete pinned Jellyfin migration history (${pinnedNativeSqliteMigrationHistory.length} rows)`);
  }
  return envelope;
}

export function parseNativeEnvelope(value) {
  if (typeof value !== 'string' || !value) throw new TypeError('Stored native database envelope must be nonempty JSON');
  let parsed;
  try { parsed = JSON.parse(value, (_, item) => parseStoredInteger(item)); }
  catch (error) { throw new Error('Stored native database envelope is not valid JSON', { cause: error }); }
  return normalizeNativeEnvelope(parsed);
}
